function x1_sync_mapping_upsert(string $userId,string $playlistId,string $remoteUuid,int $revision=0):array{$rows=x1_read('sync_mappings');$now=date('c');$row=['id'=>x1_id(),'userId'=>$userId,'playlistId'=>$playlistId,'remotePlaylistUuid'=>$remoteUuid,'lastSyncedAt'=>$now,'lastRevision'=>$revision];$found=false;foreach($rows as&$r)if((string)($r['playlistId']??'')===$playlistId||(string)($r['remotePlaylistUuid']??'')===$remoteUuid){$row=array_merge($r,$row,['id'=>$r['id']??$row['id']]);$r=$row;$found=true;break;}unset($r);if(!$found)$rows[]=$row;x1_write('sync_mappings',$rows);return $row;}function x1_cloud_push_playlists(string $sessionId,array $playlists):array{$sessions=x1_read('pairing_sessions');$session=null;foreach($sessions as $s)if((string)($s['sessionId']??'')===$sessionId&&($s['status']??'')==='confirmed'){$session=$s;break;}if(!$session)return['ok'=>false,'reason'=>'invalid_session','mapped'=>[]];$rows=x1_read('cloud_playlists');$mapped=[];$user=(string)($session['userId']??'');foreach($playlists as $p){if(!is_array($p))continue;$local=(string)($p['playlistId']??$p['id']??'');$uuid=(string)($p['playlistUuid']??$p['remotePlaylistUuid']??'');if($uuid==='')$uuid=x1_id();$revision=max(1,(int)($p['revision']??1));$rec=['id'=>x1_id(),'sessionId'=>$sessionId,'userId'=>$user,'remotePlaylistUuid'=>$uuid,'playlistUuid'=>$uuid,'name'=>(string)($p['name']??$p['playlistName']??'Playlist'),'sourceType'=>(string)($p['sourceType']??''),'payload'=>$p,'revision'=>$revision,'updatedAt'=>date('c')];$hit=false;foreach($rows as&$r)if((string)($r['remotePlaylistUuid']??'')===$uuid){$rec=array_merge($r,$rec,['id'=>$r['id']??$rec['id']]);$r=$rec;$hit=true;break;}unset($r);if(!$hit)$rows[]=$rec;if($local!=='')x1_sync_mapping_upsert($user,$local,$uuid,$revision);$mapped[]=['playlistId'=>$local,'remotePlaylistUuid'=>$uuid,'lastRevision'=>$revision];}x1_write('cloud_playlists',$rows);return['ok'=>true,'mapped'=>$mapped,'count'=>count($mapped)];}function x1_cloud_pull_playlists(string $sessionId):array{$sessions=x1_read('pairing_sessions');$session=null;foreach($sessions as $s)if((string)($s['sessionId']??'')===$sessionId&&($s['status']??'')==='confirmed'){$session=$s;break;}if(!$session)return['ok'=>false,'reason'=>'invalid_session','playlists'=>[]];$user=(string)($session['userId']??'');$rows=array_values(array_filter(x1_read('cloud_playlists'),fn($r)=>$user===''||(string)($r['userId']??'')===$user));return['ok'=>true,'playlists'=>array_map(fn($r)=>['playlistUuid'=>$r['remotePlaylistUuid']??'','remotePlaylistUuid'=>$r['remotePlaylistUuid']??'','name'=>$r['name']??'','sourceType'=>$r['sourceType']??'','revision'=>(int)($r['revision']??0),'payload'=>$r['payload']??[]],$rows)];}function x1_sync_event(string $type,string $sessionId='',array $meta=[]):void{$rows=x1_read('sync_events');$rows[]=['id'=>x1_id(),'at'=>date('c'),'type'=>$type,'sessionId'=>$sessionId,'meta'=>$meta];if(count($rows)>3000)$rows=array_slice($rows,-3000);x1_write('sync_events',$rows);}function x1_snapshot_version_next(string $remoteUuid):int{$max=0;foreach(x1_read('cloud_snapshots')as $s)if((string)($s['remotePlaylistUuid']??'')===$remoteUuid)$max=max($max,(int)($s['snapshotVersion']??0));return $max+1;}function x1_snapshot_create(string $sessionId,string $remoteUuid,array $payload,int $revision,string $mode='FULL_IMPORT'):array{$rows=x1_read('cloud_snapshots');$v=x1_snapshot_version_next($remoteUuid);$row=['id'=>x1_id(),'sessionId'=>$sessionId,'remotePlaylistUuid'=>$remoteUuid,'snapshotVersion'=>$v,'revision'=>$revision,'mode'=>$mode,'payload'=>$payload,'createdAt'=>date('c')];$rows[]=$row;if(count($rows)>5000)$rows=array_slice($rows,-5000);x1_write('cloud_snapshots',$rows);return $row;}function x1_conflict_add(string $sessionId,string $remoteUuid,string $kind,array $local,array $remote,array $meta=[]):array{$rows=x1_read('sync_conflicts');$row=['id'=>x1_id(),'sessionId'=>$sessionId,'remotePlaylistUuid'=>$remoteUuid,'kind'=>$kind,'status'=>'open','local'=>$local,'remote'=>$remote,'meta'=>$meta,'createdAt'=>date('c'),'resolvedAt'=>'','resolution'=>''];$rows[]=$row;if(count($rows)>2000)$rows=array_slice($rows,-2000);x1_write('sync_conflicts',$rows);x1_sync_event('conflict_opened',$sessionId,['conflictId'=>$row['id'],'kind'=>$kind,'remoteUuid'=>$remoteUuid]);return $row;}function x1_conflict_resolve(string $id,string $resolution):bool{$rows=x1_read('sync_conflicts');$ok=false;foreach($rows as&$r)if((string)($r['id']??'')===$id){$r['status']='resolved';$r['resolution']=$resolution;$r['resolvedAt']=date('c');$ok=true;break;}unset($r);if($ok){x1_write('sync_conflicts',$rows);x1_sync_event('conflict_resolved','',['conflictId'=>$id,'resolution'=>$resolution]);}return $ok;}function x1_session_valid(string $sessionId):?array{foreach(x1_read('pairing_sessions')as $s)if((string)($s['sessionId']??'')===$sessionId&&($s['status']??'')==='confirmed'&&(int)($s['expiresAt']??0)>=time())return $s;return null;}